import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Load Google Font
const { fontFamily: interFamily } = loadInter();

// Component Schema


export type BarChartAnimationProps = Record<string, any>;

// SVG Car Components (Flat Icons)
const GasCar: React.FC<{ color: string; opacity: number; style?: React.CSSProperties }> = ({ color, opacity, style }) => (
  <svg viewBox="0 0 200 80" style={{ width: 260, color, opacity, display: 'block', ...style }}>
    {/* Car Body */}
    <path 
      d="M 15 65 C 15 65, 10 65, 10 55 L 15 45 C 20 40, 30 35, 45 35 L 60 20 C 70 10, 80 10, 110 10 L 130 10 C 150 10, 160 20, 170 35 L 180 40 C 185 40, 190 45, 190 55 C 190 60, 190 65, 185 65 Z" 
      fill="currentColor" 
    />
    {/* Wheels */}
    <circle cx="50" cy="65" r="14" fill="currentColor" />
    <circle cx="150" cy="65" r="14" fill="currentColor" />
  </svg>
);

const EVCar: React.FC<{ color: string; opacity: number; style?: React.CSSProperties }> = ({ color, opacity, style }) => (
  <svg viewBox="0 0 200 80" style={{ width: 260, color, opacity, display: 'block', ...style }}>
    {/* Car Body */}
    <path 
      d="M 15 65 C 15 65, 10 65, 10 55 L 15 45 C 20 40, 30 35, 45 35 L 60 20 C 70 10, 80 10, 110 10 L 130 10 C 150 10, 160 20, 170 35 L 180 40 C 185 40, 190 45, 190 55 C 190 60, 190 65, 185 65 Z" 
      fill="currentColor" 
    />
    {/* Wheels */}
    <circle cx="50" cy="65" r="14" fill="currentColor" />
    <circle cx="150" cy="65" r="14" fill="currentColor" />
  </svg>
);


const BarChartAnimation: React.FC<BarChartAnimationProps> = ({
  backgroundColor = "#E6F4F8",
  transparentBackground = false,
  durationInSeconds = 6,
  chartTitle = "Cost of driving",
  gasBarColor = "#8A8D8F",
  evBarColor = "#77B143",
  gasBarHeight = 0.85,
  evBarHeight = 0.35,
  textColor = "#4A5568",
  showBranding = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background computation
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animations Timing
  // 1. Text fades in
  const textOpacity = interpolate(frame, [5, 20], [0, 1], { extrapolateRight: 'clamp' });

  // 2. Base line grows from center
  const lineWidthPercent = spring({ frame: frame - 15, fps, config: { damping: 20 } });

  // 3. Cars fade in
  const carsOpacity = interpolate(frame, [20, 30], [0, 1], { extrapolateRight: 'clamp' });

  // 4. Bars spring up (pushing cars)
  const gasBarProgress = spring({ frame: frame - 30, fps, config: { damping: 14, mass: 1.2 } });
  const evBarProgress = spring({ frame: frame - 40, fps, config: { damping: 14, mass: 1.2 } });

  // 5. Dollar signs fade in
  const dollarsOpacity = interpolate(frame, [60, 75], [0, 1], { extrapolateRight: 'clamp' });

  // Layout Dimensions
  const chartAreaHeight = height * 0.55;
  const barWidth = 320;
  
  const currentGasHeight = gasBarProgress * (chartAreaHeight * gasBarHeight);
  const currentEvHeight = evBarProgress * (chartAreaHeight * evBarHeight);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, color: textColor, transition: "none" }}>
      
      {/* Main Chart Area */}
      <div 
        style={{ 
          position: 'absolute', 
          bottom: '22%', 
          left: '10%', 
          right: '10%', 
          height: chartAreaHeight, 
          display: 'flex', 
          flexDirection: 'column', 
          justifyContent: 'flex-end',
          alignItems: 'center',
          transition: "none"
        }}
      >
        {/* Bars and Cars Flex Container */}
        <div 
          style={{ 
            display: 'flex', 
            flexDirection: 'row', 
            justifyContent: 'center', 
            alignItems: 'flex-end', 
            gap: width * 0.15, 
            width: '100%', 
            height: '100%',
            transition: "none",
            zIndex: 2
          }}
        >
          {/* Gas Column */}
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'flex-end', transition: "none" }}>
            <GasCar color={gasBarColor} opacity={carsOpacity} />
            <div 
              style={{ 
                width: barWidth, 
                height: currentGasHeight, 
                backgroundColor: gasBarColor, 
                display: 'flex', 
                alignItems: 'flex-end', 
                justifyContent: 'center', 
                paddingBottom: 30,
                transition: "none"
              }}
            >
              <span style={{ color: 'white', fontSize: 80, fontWeight: 'bold', opacity: dollarsOpacity, transition: "none" }}>
                $
              </span>
            </div>
          </div>

          {/* EV Column */}
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'flex-end', transition: "none" }}>
            <EVCar color={evBarColor} opacity={carsOpacity} />
            <div 
              style={{ 
                width: barWidth, 
                height: currentEvHeight, 
                backgroundColor: evBarColor, 
                display: 'flex', 
                alignItems: 'flex-end', 
                justifyContent: 'center', 
                paddingBottom: 30,
                transition: "none"
              }}
            >
              <span style={{ color: 'white', fontSize: 80, fontWeight: 'bold', opacity: dollarsOpacity, transition: "none" }}>
                $
              </span>
            </div>
          </div>
        </div>

        {/* Base Line */}
        <div 
          style={{ 
            height: 2, 
            backgroundColor: '#888', 
            width: `${lineWidthPercent * 85}%`, 
            alignSelf: 'center',
            marginTop: 0,
            zIndex: 1,
            transition: "none"
          }} 
        />
      </div>

      {/* Chart Title */}
      <div 
        style={{ 
          position: 'absolute', 
          bottom: '10%', 
          width: '100%', 
          textAlign: 'center', 
          fontSize: 60, 
          fontWeight: 600, 
          opacity: textOpacity,
          transition: "none"
        }}
      >
        {chartTitle}
      </div>

      {/* Branding (Optional) */}
      {showBranding && (
        <div 
          style={{ 
            position: 'absolute', 
            bottom: 40, 
            right: 60, 
            fontSize: 32, 
            fontWeight: 700, 
            opacity: textOpacity,
            display: 'flex',
            alignItems: 'center',
            transition: "none"
          }}
        >
          <span style={{ color: evBarColor, marginRight: 2 }}>-</span>
          <span style={{ color: textColor }}>malloy</span>
          <span style={{ color: gasBarColor, marginLeft: 2 }}>+</span>
        </div>
      )}
    </AbsoluteFill>
  );
};

export default BarChartAnimation;